for mid,txt in c.execute('select id,content from messages where session_id=? and role=? order by id',(sid,'user')):
 if not txt or 'Demo pair' not in txt: continue
 m=re.search(r'Demo pair (\d+) input \((\d+)x(\d+)\):\n(.*?)\nDemo pair \1 output \(\2x\3\):\n(.*?)(?:\n\nSame instance|\Z)',txt,re.S); n,h,w,ain,aout=m.groups(); a=[list(map(int,l.split())) for l in ain.strip().splitlines()]; b=[list(map(int,l.split())) for l in aout.strip().splitlines()]; bg=collections.Counter(v for row in a for v in row).most_common(1)[0][0];
 changed={(r,col) for r in range(len(a)) for col in range(len(a[0])) if a[r][col]!=b[r][col]}; seen=set(); comps=[]
 for r in range(len(a)):
  for col in range(len(a[0])):
   co=a[r][col]
   if co==bg or (r,col) in seen: continue
   todo=[(r,col)]; seen.add((r,col)); cells=[]
   while todo:
    y,x=todo.pop(); cells.append((y,x))
    for yy,xx in ((y+1,x),(y-1,x),(y,x+1),(y,x-1)):
     if 0<=yy<len(a) and 0<=xx<len(a[0]) and a[yy][xx]==co and (yy,xx) not in seen: seen.add((yy,xx));todo.append((yy,xx))
   comps.append((co,cells))
 print('\nDEMO',n,'bg',bg,'changed',sorted(changed))
 for co,cells in sorted(comps,key=lambda t:(min(y for y,x in t[1]),min(x for y,x in t[1]))):
  rr=[y for y,x in cells]; cc=[x for y,x in cells]; bb=(min(rr),min(cc),max(rr),max(cc)); mark='*' if changed.intersection(cells) else ''
  print(' color',co,'n',len(cells),'box',bb,mark,'cells',cells if len(cells)<15 else '')

